        /// <exception cref="Interserver.MyAdmin.Client.Client.ApiException">Thrown when fails to make API call</exception>
        /// <param name="id">The credit card ID to remove. Use IDs from &#x60;GET /billing/creditcards&#x60;.</param>
        /// <returns>Task of SuccessTextResponse</returns>
        System.Threading.Tasks.Task<SuccessTextResponse> DeleteBillingCreditCardAsync (int? id);

